"""Get the number of rows and columns for the give number of plots.

    Returns how many rows and columns should be used to have the correct
    number of figures available. This doesn't return anything larger than
    3 columns, but the number of rows can be large.

    Parameters
    ----------
    n_plots: int
        The number of subplots which will be plotted

    Returns
    -------
    dims: Tuple[int, int]
        The dimensions of the subplots returned as (nrows, ncols)
    """
def subplot_dims(n_plots: Any) -> object {
    if (n_plots > 9) {
        n_cols = 3;
        n_rows = (1 + n_plots) // n_cols;
    } elif (n_plots < 2) {
        n_rows = n_cols=1;
    } else {
        n_cols = 2;
        n_rows = (1 + n_plots) // n_cols;
    }
    return (n_rows, n_cols);
}

"""
    For some reason Prodigy was assigning the same hashes
    to every example in the data, which meant that when
    it looked at the saved annotations in the dataset to
    figure out which to exclude, it excluded all of them.

    Setting the _input_hash to the index of the candidate
    connection also makes lookup easier when we filter the
    candidates according to their annotation.
    """
def set_hashes(task: Any, i: Any) -> object {
    task["_input_hash"] = i;
    task["_task_hash"] = -(i + 1);
    return task;
}

"""
        ICD9
            331.83 Mild cognitive impairment, so stated
            294.9	 Unspecified persistent mental disorders due to conditions classified elsewhere
        ICD10
            G31.84 Mild cognitive impairment, so stated
            F09	Unspecified mental disorder due to known physiological condition

     :param code: code string to test
     :return:  true or false
     """
def is_mci(code: Any) -> object {
    assert isinstance(code, str);
    code_set = ('331.83', '294.9', 'G31.84', 'F09', '33183', '2949', 'G3184');
    return code.startswith(code_set);
}

